styles:
/* Custom scrollbar for webkit browsers */
        ::-webkit-scrollbar {
            width: 8px;
            height: 8px;
        }
        ::-webkit-scrollbar-track {
            background: #101922; 
        }
        ::-webkit-scrollbar-thumb {
            background: #2b8cee; 
            border-radius: 4px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: #1a5bb0; 
        }
